<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Record expense · LRC</title><style>body{font:15px system-ui;background:#f4f6f8;margin:28px}main{max-width:650px;margin:auto;background:#fff;padding:26px;border-radius:12px}label{display:block;margin:14px 0 5px}input,select,textarea{width:100%;padding:10px;border:1px solid #ccd3d9;border-radius:6px}button{margin-top:18px;padding:10px 16px}</style></head><body><main><a href="{{ route('accounting.expenses.index') }}">← Expenses</a><h1>Record property expense</h1><p>New expenses are pending and cannot affect owner statements until another authorized user approves them.</p><form method="post" action="{{ route('accounting.expenses.store') }}">@csrf<label>Property</label><select name="property_id" required>@foreach($properties as $property)<option value="{{ $property->id }}">{{ $property->name }}</option>@endforeach</select><label>Category</label><select name="category" required>@foreach(['repairs','maintenance','utilities','security','tax','insurance','cleaning','other'] as $category)<option value="{{ $category }}">{{ ucfirst($category) }}</option>@endforeach</select><label>Description</label><input name="description" maxlength="255" required><label>Date incurred</label><input type="date" name="incurred_on" max="{{ now()->toDateString() }}" required><label>Amount (RWF)</label><input type="number" name="amount" min="0.01" step="0.01" required><label>Charge to owner?</label><select name="charge_to_owner"><option value="1">Yes, subject to agreement</option><option value="0">No, LRC expense</option></select><button type="submit">Save pending expense</button></form></main></body></html>